#!/usr/bin/env python3
"""Import the existing pinned ProjectReach English system-message catalog."""
import argparse,hashlib,json,pathlib,re
R=pathlib.Path(__file__).resolve().parents[1];p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args()
source=R/'ref/halopad/port/runtime/halopad_k32_time.c';lock=json.loads((R/'dependencies.lock.json').read_text());revision=next(s['revision'] for s in lock['sources'] if s['name']=='halopad');assert revision=='c4aad6873057e48cb7e6aca907797722ef7da5b9'
assert hashlib.sha256(source.read_bytes()).hexdigest()=='1a55b7a6079b84b27309d8b09b4594f164054b9a0cab926e9a763bcfdde2d602'
text=source.read_text();start=text.index('static const struct { uint32_t id; const char *text; } messages[] = {');end=text.index('\n};',start)+3;table=text[start:end];rows=re.findall(r'\{(\d+),\s*("(?:[^"\\]|\\.)*")\}',table)
assert len(rows)==table.count('{')-2 and rows;entries={int(k):json.loads(v) for k,v in rows};assert len(entries)==len(rows) and all(t.isascii() and '%' not in t and t.endswith('\r\n') for t in entries.values())
sha=hashlib.sha256(source.read_bytes()).hexdigest();header='/* Generated by gen-system-messages.py from the pinned ProjectReach message catalog.\n   Revision '+revision+'; source SHA256 '+sha+'.\n   Finite English catalog: unlisted message IDs remain explicit runtime stops. */\n'
header+='static const struct {uint32_t id;const char *text;} system_messages[]={\n'+''.join(' {%du,%s},\n'%(k,json.dumps(v)) for k,v in sorted(entries.items()))+'};\n'
output=R/'port/core/system_messages.inc';metadata=R/'config/runtime/system-messages.json';record=dict(source=str(source.relative_to(R)),source_sha256=sha,revision=revision,language=0x409,messages=entries,scope='Existing finite ProjectReach US-English system-message catalog; no all-Windows-resource coverage. Unlisted IDs are explicit diagnostic stops.')
encoded=json.dumps(record,indent=2)+'\n'
if a.check:assert output.read_text()==header and metadata.read_text()==encoded
else:output.write_text(header);metadata.write_text(encoded)
print('PASS: %d source-bound system messages'%len(entries))
